{"command":"BASE=$(cat /tmp/base.txt); cd "$BASE" && cat > /tmp/build_union.mjs << 'EOF'
import { readFileSync, writeFileSync } from 'node:fs';
const depts = ['access','data','dependencies','injection','platform','secrets'];
const all = [];
for (const d of depts) {
  const arr = JSON.parse(readFileSync(`findings/${d}.json`,'utf8'));
  for (const f of arr) all.push({dept:d, f});
}
const CONF_RANK = {confirmed:3, likely:2, possible:1};
const kept = new Map(); // key -> {dept,f}
const droppedDueToDedup = [];
for (const {dept,f} of all) {
  const key = `${f.file}:${f.line}:${f.cwe}`;
  if (!kept.has(key)) {
    kept.set(key, {dept, f});
  } else {
    const existing = kept.get(key);
    const rankNew = CONF_RANK[f.confidence];
    const rankOld = CONF_RANK[existing.f.confidence];
    if (rankNew > rankOld) {
      droppedDueToDedup.push({id: existing.f.id, keptId: f.id, key});
      kept.set(key, {dept, f});
    } else {
      // keep existing (first-seen wins ties, or existing has higher/equal confidence)
      droppedDueToDedup.push({id: f.id, keptId: existing.f.id, key});
    }
  }
}
const union = [...kept.values()].map(x => x.f);
console.log('Total input findings:', all.length);
console.log('Total kept:', union.length);
console.log('Dropped due to dedup:');
for (const d of droppedDueToDedup) console.log(' -', d.id, '-> kept', d.keptId, '(' + d.key + ')');
writeFileSync('/tmp/findings.union.json', JSON.stringify(union, null, 2) + '\n');
EOF
